# Climate damages to one household's electricity use
# ECON 4210 -- Economics of Climate Change
#
# Interactive version of the class 10 exercise. Estimates a weather-response
# function from daily electricity use and projects use under a warmer climate.
#
# Data files (same folder):
#   energy_kwh.csv              daily kWh and temperature, from build_energy_data.R
#   cmip6_quantile_deltas.csv   from get_cmip6.R (optional)
#
# Runs as a regular Shiny app or in the browser through Shinylive:
#   shinylive::export("damage_app", "../../website/damage-app")
# Base R and ggplot2 only, to keep the in-browser load short.

library(shiny)
library(bslib)
library(ggplot2)

# ---------------------------------------------------------------------------
# Data
# ---------------------------------------------------------------------------
d <- read.csv("energy_kwh.csv")
d$date <- as.Date(d$date)
d$dow <- factor(d$dow, levels = c("Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"))

# percentile of each day's temperature within its calendar month
d$pct <- ave(d$tavg, d$month, FUN = function(x) {
  pmin(pmax(round(rank(x) / (length(x) + 1), 2), 0.01), 0.99)
})

t_max_obs <- max(d$tavg)
t_min_obs <- min(d$tavg)
price_default <- round(with(d[d$date > max(d$date) - 365, ], sum(cost) / sum(kwh)), 3)

has_cmip <- file.exists("cmip6_quantile_deltas.csv")
if (has_cmip) {
  qdelta <- read.csv("cmip6_quantile_deltas.csv")
  cmip_models <- sort(unique(qdelta$model))
}

col_obs  <- "#2A62A8"
col_proj <- "#B8432C"
col_ink  <- "#1f2328"
col_alt  <- "#D08A00"   # alternative equipment (line)
col_alt_text <- "#8F5F00"  # darker shade for its label

# ---------------------------------------------------------------------------
# Weather-response functions
# ---------------------------------------------------------------------------
bin_edges <- c(-Inf, seq(35, 85, 5), Inf)
bin_levels <- levels(cut(0, bin_edges, right = FALSE))
make_bins <- function(t) {
  relevel(factor(cut(t, bin_edges, right = FALSE), levels = bin_levels), ref = "[60,65)")
}

forms <- c(
  "Linear"             = "linear",
  "Quadratic"          = "quadratic",
  "Cubic"              = "cubic",
  "5°F temperature bins" = "bins"
)

formula_for <- function(form) {
  switch(form,
    linear    = kwh ~ tavg + dow,
    quadratic = kwh ~ tavg + I(tavg^2) + dow,
    cubic     = kwh ~ tavg + I(tavg^2) + I(tavg^3) + dow,
    bins      = kwh ~ tbin + dow
  )
}

d$tbin <- make_bins(d$tavg)
fits <- lapply(forms, function(f) lm(formula_for(f), data = d))
names(fits) <- forms

predict_kwh_est <- function(fit, tavg, dow) {
  predict(fit, data.frame(tavg = tavg, tbin = make_bins(tavg), dow = dow))
}

# ---------------------------------------------------------------------------
# Alternative equipment (illustrative, not estimated)
#
# The fitted curve is split at its lowest point between 55 and 65 deg F.
# Use above that level on the hot side is treated as cooling, and on the cold
# side as heating-related electricity (furnace blower, etc.). Heating stays on
# the gas furnace in every case. Each option scales one or both parts by a
# fixed coefficient.
# ---------------------------------------------------------------------------
equipment <- c(
  "Current central AC (estimated)" = "current",
  "Window AC units (less efficient)" = "window",
  "Heat pump AC (more efficient) " = "heatpump"
)
cool_mult <- c(current = 1, window = 1.4, heatpump = 0.6)

# insulation and replacement of the original 1910 single-pane windows
envelope_mult <- 0.75

balance_point <- function(fit) {
  tt <- seq(55, 65, by = 0.5)
  tt[which.min(predict_kwh_est(fit, tt, factor("Wed", levels = levels(d$dow))))]
}

# kWh under the chosen equipment: the estimated prediction plus the change
# in the cooling or heating part implied by the multipliers
predict_kwh <- function(fit, tavg, dow, equip = "current", envelope = FALSE) {
  est <- predict_kwh_est(fit, tavg, dow)
  m_cool <- cool_mult[[equip]] * ifelse(envelope, envelope_mult, 1)
  m_heat <- ifelse(envelope, envelope_mult, 1)
  if (m_cool == 1 && m_heat == 1) return(est)
  tb <- balance_point(fit)
  # day-of-week effects are additive, so any reference day gives the same shape
  wed <- factor("Wed", levels = levels(d$dow))
  above_base <- predict_kwh_est(fit, tavg, wed) - predict_kwh_est(fit, tb, wed)
  m <- ifelse(tavg > tb, m_cool, m_heat)
  est + (m - 1) * pmax(above_base, 0)
}

# ---------------------------------------------------------------------------
# Projected temperatures for each observed day
# ---------------------------------------------------------------------------
# Each observed day gets the model's temperature change at that day's
# percentile within its calendar month (quantile delta mapping).
shift_for_model <- function(model, scenario, period) {
  q <- qdelta[qdelta$model == model & qdelta$scenario == scenario &
                qdelta$period == period, ]
  key <- paste(q$month, sprintf("%.2f", q$p))
  q$delta_f[match(paste(d$month, sprintf("%.2f", d$pct)), key)]
}

impact <- function(fit, t_new, price, co2_rate, equip = "current", envelope = FALSE) {
  now <- predict_kwh(fit, d$tavg, d$dow, equip, envelope)
  fut <- predict_kwh(fit, t_new, d$dow, equip, envelope)
  dk <- mean(fut) - mean(now)
  c(
    kwh_now   = mean(now),
    pct       = 100 * dk / mean(now),
    kwh_year  = 365 * dk,
    cost_year = 365 * dk * price,
    co2_year  = 365 * dk * co2_rate / 1000 / 2204.62,
    out       = 100 * mean(t_new > t_max_obs)
  )
}

scenario_labels <- c("SSP2-4.5 (intermediate GHG emissions)" = "ssp245",
                     "SSP5-8.5 (high GHG emissions)" = "ssp585")
period_labels <- c("2041–2060" = "2041-2060", "2081–2100" = "2081-2100")

# ---------------------------------------------------------------------------
# UI
# ---------------------------------------------------------------------------
# Styling follows the course website (caseyjwichman.com/econ4210): warm
# neutral ground, slate ink, deep sea teal accent, metadata set in mono.
site <- list(
  paper = "#faf8f4", card = "#ffffff", ink = "#1f2328", body = "#3f464f",
  mute = "#7d848d", faint = "#a8aeb6", rule = "#e6e2da", teal = "#2f6d78",
  slate = "#46586e"
)
sans_stack <- '-apple-system, BlinkMacSystemFont, "Segoe UI", Inter, Helvetica, Arial, sans-serif'
mono_stack <- 'ui-monospace, SFMono-Regular, "SF Mono", Menlo, Consolas, monospace'

theme <- bs_theme(
  version = 5, bg = site$paper, fg = site$body, primary = site$teal,
  base_font = sans_stack, code_font = mono_stack,
  "font-size-base" = "0.95rem", "border-color" = site$rule,
  "card-bg" = site$card, "card-border-color" = site$rule, "card-cap-bg" = site$card
)

site_css <- sprintf("
  :root { --paper:%1$s; --card:%2$s; --ink:%3$s; --body:%4$s; --mute:%5$s;
          --faint:%6$s; --rule:%7$s; --teal:%8$s; --slate:%9$s; --mono:%10$s; }
  body { -webkit-font-smoothing: antialiased; }

  /* masthead */
  .masthead { padding: 0.9rem 0.5rem 0.6rem; white-space: normal; }
  .masthead .eyebrow { font: 600 0.68rem/1 var(--mono); letter-spacing: 0.16em;
    text-transform: uppercase; color: var(--teal); margin: 0 0 0.55rem; }
  .masthead h1 { margin: 0; font-size: 1.45rem; line-height: 1.2; font-weight: 600;
    color: var(--ink); letter-spacing: -0.018em; }
  .masthead .sub { margin: 0.35rem 0 0; font: 0.8rem/1.5 var(--mono); color: var(--mute); }
  .masthead .sub a { color: var(--slate); text-decoration: none;
    border-bottom: 1px solid #cfd6de; }
  .masthead .sub a:hover { border-bottom-color: var(--slate); }
  .bslib-page-title, .navbar { background: var(--paper) !important;
    border-bottom: 1px solid var(--rule) !important; }

  /* sidebar */
  .bslib-sidebar-layout > .sidebar { background: var(--paper);
    border-right: 1px solid var(--rule); }
  .sidebar .control-label, .sidebar .form-label, .sidebar-group-label {
    font: 600 0.68rem/1.3 var(--mono); letter-spacing: 0.12em;
    text-transform: uppercase; color: var(--mute); margin-bottom: 0.45rem; }
  .sidebar hr { border-color: var(--rule); opacity: 1; }
  .form-select, .form-control { border-color: var(--rule); border-radius: 4px; }
  .form-check-input { border: 1px solid #9aa1a9 !important; }
  .form-check-input:checked { border-color: var(--teal) !important; }
  .form-check-input:checked { background-color: var(--teal); border-color: var(--teal); }
  .irs--shiny .irs-bar, .irs--shiny .irs-single { background: var(--teal); border-color: var(--teal); }
  .irs--shiny .irs-handle { border-color: var(--teal); }

  /* cards */
  .card { border: 1px solid var(--rule); border-radius: 5px; box-shadow: none; }
  .card-header, .bslib-card .card-header { background: var(--card); border-bottom: 1px solid var(--rule);
    font: 600 0.68rem/1.4 var(--mono); letter-spacing: 0.1em; text-transform: uppercase;
    color: var(--teal); }
  .nav-tabs .nav-link { font: 500 0.78rem/1 var(--mono); letter-spacing: 0.04em;
    color: var(--mute); }
  .nav-tabs .nav-link.active { color: var(--ink); }
  .nav-tabs .nav-link:hover { color: var(--teal); }

  /* stat tiles */
  .stat-row { display: grid; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); gap: 12px; }
  .stat-tile { background: var(--card); border: 1px solid var(--rule); border-radius: 5px;
    padding: 0.7rem 0.9rem; }
  .stat-label { font: 600 0.64rem/1.35 var(--mono); letter-spacing: 0.1em;
    text-transform: uppercase; color: var(--faint); }
  .stat-value { margin-top: 0.3rem; font-size: 1.45rem; font-weight: 600; color: var(--ink);
    letter-spacing: -0.01em; font-variant-numeric: tabular-nums; }

  /* accordions, styled like the course-information panel */
  .accordion { --bs-accordion-border-color: var(--rule); --bs-accordion-bg: var(--card);
    --bs-accordion-active-bg: var(--card); --bs-accordion-btn-focus-box-shadow: none;
    --bs-accordion-active-color: var(--ink); }
  .accordion-button { font: 600 0.7rem/1 var(--mono); letter-spacing: 0.13em;
    text-transform: uppercase; color: var(--mute); padding: 0.9rem 1rem; }
  .accordion-button:not(.collapsed) { color: var(--ink); box-shadow: none; }

  .note { font-size: 0.85rem; color: var(--mute); }
  .ts-controls { display: flex; flex-wrap: wrap; gap: 4px 24px; font-size: 0.9rem; }
  .ts-controls .form-group { margin-bottom: 0; }
", site$paper, site$card, site$ink, site$body, site$mute, site$faint, site$rule,
   site$teal, site$slate, mono_stack)

# shared ggplot theme: white card ground, recessive grid, muted axis text
theme_site <- function() {
  theme_minimal(base_size = 14, base_family = "sans") +
    theme(panel.grid.minor = element_blank(),
          panel.grid.major = element_line(colour = "#efece5"),
          axis.text = element_text(colour = site$mute),
          axis.title = element_text(colour = site$body),
          strip.text = element_text(colour = site$ink))
}

stat_tile <- function(id, label) {
  div(class = "stat-tile",
      div(class = "stat-label", label),
      div(class = "stat-value", textOutput(id, inline = TRUE)))
}

ui <- page_sidebar(
  title = div(class = "masthead",
    p(class = "eyebrow", "ECON 4210 \u00b7 Class 10 \u00b7 Climate damage functions"),
    h1("How would a warmer climate change Prof. Wichman's electricity use?"),
    p(class = "sub", "Daily Georgia Power data, DeKalb County, GA \u00b7 ",
      a("Course website", href = "https://www.caseyjwichman.com/econ4210/",
        target = "_blank", rel = "noopener"))
  ),
  window_title = "Climate damages to electricity use \u2014 ECON 4210",
  theme = theme,
  tags$head(tags$style(HTML(site_css))),
  sidebar = sidebar(
    width = 320,
    radioButtons("climate", "Future climate:",
                 choices = c("Uniform temp. increase" = "uniform",
                             "CMIP6 climate model projection" = "cmip6"),
                 selected = "uniform"),
    conditionalPanel(
      "input.climate == 'uniform'",
      sliderInput("shift", "Temp. increase (°F added to every day)",
                  min = 0, max = 10, value = 4, step = 0.5)
    ),
    conditionalPanel(
      "input.climate == 'cmip6'",
      if (has_cmip) tagList(
        selectInput("scenario", "Emissions scenario", scenario_labels, selectize = FALSE),
        selectInput("period", "Time period", period_labels, selectize = FALSE),
        selectInput("model", "Climate model",
                    c("Average of all models" = "all", cmip_models), selectize = FALSE)
      ) else p(class = "note", "CMIP6 projections not yet loaded. Run get_cmip6.R.")
    ),
    hr(),
    selectInput("form", "Weather-response function: f(temperature)", forms,
                selected = "quadratic", selectize = FALSE),
    radioButtons("equip", "Cooling equipment (adaptation)", equipment,
                 selected = "current"),
    checkboxInput("envelope",
                  "Prof. Wichman invests in insulation and replaces the original 1910 single-pane windows",
                  value = FALSE),
    p(class = "note",
      "Equipment options other than the current AC are illustrative. ",
      "They rescale the estimated curve by fixed coefficients and are not estimated from data."),
    hr(),
    numericInput("price", "Electricity price ($/kWh)", price_default,
                 min = 0.05, max = 0.5, step = 0.01),
    numericInput("co2", "Grid emissions (lb CO₂ per MWh)", 842,
                 min = 0, max = 2500, step = 10),
    p(class = "note",
      "Default price: average paid over the last 12 months of data. ",
      "Default emissions: EPA eGRID 2023, SERC South subregion.")
  ),
  layout_columns(
    col_widths = c(7, 5), fill = FALSE,
    navset_card_tab(
      id = "view",
      selected = "Over time",
      nav_panel(
        "Over time",
        div(class = "ts-controls",
            checkboxInput("ts_warmer", "Show the warmer climate", value = FALSE),
            radioButtons("smooth", NULL, inline = TRUE,
                         c("Daily" = "1", "7-day average" = "7", "30-day average" = "30"),
                         selected = "30"),
            radioButtons("ts_unit", NULL, inline = TRUE,
                         c("kWh" = "kwh", "Dollars" = "usd"), selected = "kwh")),
        div(plotOutput("p_ts", height = "440px")),
        div(class = "note", textOutput("ts_note"))
      ),
      nav_panel(
        "Weather-response function",
        div(plotOutput("p_response", height = "360px")),
        div(class = "note", textOutput("fit_note"))
      )
    ),
    card(card_header("Daily temperatures, observed and projected"),
         div(plotOutput("p_hist", height = "360px")))
  ),
  div(class = "stat-row",
      stat_tile("s_pct", "Change in daily use"),
      stat_tile("s_kwh", "Extra kWh per year"),
      stat_tile("s_cost", "Extra cost per year"),
      stat_tile("s_co2", "Extra CO₂ per year"),
      stat_tile("s_out", "Projected days hotter than any observed day")),
  conditionalPanel(
    "input.climate == 'cmip6' && input.model == 'all'",
    accordion(
      open = FALSE,
      accordion_panel(
        "Projected change in daily use, by climate model",
        plotOutput("p_models", height = "260px")
      )
    )
  ),
  accordion(
    open = FALSE,
    accordion_panel(
      "About the data and methods",
      p("Daily electricity use (kWh) for Prof. Wichman's house in DeKalb County, GA, from Georgia Power, ",
        textOutput("sample_dates", inline = TRUE), ". Temperatures are the daily high and low ",
        "reported in the Georgia Power usage data. Every specification includes ",
        "day-of-week indicators."),
      p("Projected use holds the weather-response function fixed and changes the ",
        "temperature only."),
      p("The equipment options are illustrative. The estimated curve is split at its ",
        "lowest point between 55 and 65°F. Use above that level on the hot side is ",
        "treated as cooling. Window AC units multiply cooling use by ",
        cool_mult[["window"]], " and an efficient heat pump by ", cool_mult[["heatpump"]],
        ". Heating stays on the gas furnace. Insulation and new windows multiply both ",
        "the cooling part and the heating-related electricity on the cold side by ",
        envelope_mult, ". The stat tiles compare future and current climate with the ",
        "same equipment in both."),
      p("CMIP6 projections come from NASA NEX-GDDP-CMIP6 at the grid cell over DeKalb County. ",
        "Changes are measured against each model's own 1995–2014 climate. Each observed ",
        "day gets the model's change at that day's percentile within its calendar month, ",
        "so hot days can warm more than mild days.")
    )
  )
)

# ---------------------------------------------------------------------------
# Server
# ---------------------------------------------------------------------------
server <- function(input, output, session) {

  fit <- reactive(fits[[input$form]])

  alt_on <- reactive(input$equip != "current" || isTRUE(input$envelope))
  alt_label <- reactive({
    short <- c(current = "Current AC", window = "Window AC units", heatpump = "Heat pump")
    paste0(short[[input$equip]], if (isTRUE(input$envelope)) " + insulation and windows" else "")
  })

  # projected temperatures: a matrix with one column per climate model
  t_new <- reactive({
    if (input$climate == "uniform" || !has_cmip) {
      return(matrix(d$tavg + input$shift, ncol = 1))
    }
    req(input$scenario, input$period, input$model)
    mods <- if (input$model == "all") cmip_models else input$model
    sapply(mods, function(m) d$tavg + shift_for_model(m, input$scenario, input$period))
  })

  res <- reactive({
    tn <- t_new()
    per_model <- apply(tn, 2, function(t) {
      impact(fit(), t, input$price, input$co2, input$equip, input$envelope)
    })
    list(mean = rowMeans(per_model), by_model = per_model)
  })

  fmt_signed <- function(x, digits = 0) {
    paste0(ifelse(x >= 0, "+", "−"), formatC(abs(x), format = "f", digits = digits, big.mark = ","))
  }
  output$s_pct  <- renderText(paste0(fmt_signed(res()$mean["pct"], 1), "%"))
  output$s_kwh  <- renderText(fmt_signed(res()$mean["kwh_year"]))
  output$s_cost <- renderText(sub("^([+−])", "\\1$", fmt_signed(res()$mean["cost_year"])))
  output$s_co2  <- renderText(paste(fmt_signed(res()$mean["co2_year"], 2), "t"))
  output$s_out  <- renderText(paste0(formatC(res()$mean["out"], format = "f", digits = 0), "%"))

  output$sample_dates <- renderText(
    paste(format(min(d$date), "%B %Y"), "to", format(max(d$date), "%B %Y"),
          sprintf("(%s days)", format(nrow(d), big.mark = ",")))
  )

  output$fit_note <- renderText({
    s <- summary(fit())
    alt <- if (alt_on()) {
      sprintf(" Dashed: %s (illustrative, not estimated).", alt_label())
    } else ""
    sprintf("%s fit, R² = %.2f, curve averaged across days of the week. Points: observed days. Ticks along the bottom: projected temperatures. Shaded: hotter than the hottest observed day (%.1f°F).%s",
            names(forms)[forms == input$form], s$r.squared, t_max_obs, alt)
  })

  output$p_response <- renderPlot({
    grid <- seq(floor(t_min_obs), 100, by = 0.5)
    # curves averaged over the seven day-of-week effects
    avg_curve <- function(equip, envelope) {
      rowMeans(sapply(levels(d$dow), function(w) {
        predict_kwh(fit(), grid, factor(rep(w, length(grid)), levels = levels(d$dow)),
                    equip, envelope)
      }))
    }
    curve <- data.frame(tavg = grid, fit = avg_curve("current", FALSE))
    alt <- data.frame(tavg = grid, fit = avg_curve(input$equip, input$envelope))
    tn <- rowMeans(t_new())
    proj <- data.frame(tavg = tn)
    ytop <- max(80, curve$fit, alt$fit) * 1.15
    ggplot() +
      annotate("rect", xmin = t_max_obs, xmax = 100, ymin = -Inf, ymax = Inf,
               fill = "#eceef0") +
      geom_point(data = d, aes(tavg, kwh), shape = 1, colour = col_obs,
                 alpha = 0.45, size = 1.6) +
      geom_line(data = curve, aes(tavg, fit), colour = col_ink, linewidth = 1) +
      {if (alt_on()) geom_line(data = alt, aes(tavg, fit), colour = col_alt,
                               linewidth = 1.5, linetype = "42")} +
      annotate("text", x = floor(t_min_obs), y = ytop * 0.99, vjust = 1, hjust = 0, size = 3.8,
               label = "Solid: estimated", colour = col_ink, fontface = "bold") +
      {if (alt_on()) annotate("text", x = floor(t_min_obs), y = ytop * 0.92, vjust = 1, hjust = 0,
                              size = 3.8, lineheight = 0.95,
                              label = paste(strwrap(paste("Dashed:", alt_label()), 30),
                                            collapse = "\n"),
                              colour = col_alt_text, fontface = "bold")} +
      geom_rug(data = proj, aes(x = tavg), colour = col_proj, alpha = 0.25,
               sides = "b", length = unit(0.04, "npc")) +
      scale_x_continuous(breaks = seq(20, 100, 10), limits = c(floor(t_min_obs), 100)) +
      coord_cartesian(ylim = c(0, ytop)) +
      labs(x = "Average daily temperature (°F)", y = "Daily electricity use (kWh)") +
      theme_site() +
      theme(panel.grid.minor = element_blank())
  }, res = 96)

  # Daily series: observed use, adjusted for the chosen equipment, under the
  # current climate and under the projected climate. Each day keeps its
  # observed noise. Only the predicted change from equipment and from warming
  # is added.
  ts_data <- reactive({
    est_now <- predict_kwh_est(fit(), d$tavg, d$dow)
    eq_now  <- predict_kwh(fit(), d$tavg, d$dow, input$equip, input$envelope)
    tn <- t_new()
    eq_fut <- rowMeans(apply(tn, 2, function(t) {
      predict_kwh(fit(), t, d$dow, input$equip, input$envelope)
    }))
    scale <- if (input$ts_unit == "usd") input$price else 1
    data.frame(
      date      = d$date,
      current   = (d$kwh + eq_now - est_now) * scale,
      warmer    = (d$kwh + eq_fut - est_now) * scale,
      temp_now  = d$tavg,
      temp_warm = rowMeans(tn)
    )
  })

  # Two stacked panels on a shared date axis: electricity use on top and
  # average daily temperature below. Blue is the current climate and red the
  # warmer climate in both panels.
  output$p_ts <- renderPlot({
    s <- ts_data()
    k <- as.integer(input$smooth)
    roll <- function(x) if (k == 1) x else as.numeric(stats::filter(x, rep(1 / k, k), sides = 2))
    use_lab  <- if (input$ts_unit == "usd") "Electricity cost ($ per day)" else "Electricity use (kWh per day)"
    temp_lab <- "Average temperature (°F)"
    panels <- c(use_lab, temp_lab)
    long <- function(y, panel, climate) {
      data.frame(date = s$date, y = roll(y), panel = panel, climate = climate)
    }
    lines <- rbind(long(s$current, use_lab, "Current climate"),
                   long(s$temp_now, temp_lab, "Current climate"))
    if (isTRUE(input$ts_warmer)) {
      lines <- rbind(lines,
                     long(s$warmer, use_lab, "Warmer climate"),
                     long(s$temp_warm, temp_lab, "Warmer climate"))
    }
    lines$panel <- factor(lines$panel, levels = panels)
    lines$climate <- factor(lines$climate, levels = c("Current climate", "Warmer climate"))
    pts <- data.frame(date = s$date, y = s$current,
                      panel = factor(use_lab, levels = panels))
    key <- data.frame(
      date = min(s$date), y = Inf, vjust = c(1.5, 3.2),
      label = c("Current climate", "Warmer climate"),
      climate = factor(c("Current climate", "Warmer climate"),
                       levels = c("Current climate", "Warmer climate")),
      panel = factor(use_lab, levels = panels)
    )
    if (!isTRUE(input$ts_warmer)) key <- key[1, ]
    ggplot() +
      {if (k > 1) geom_point(data = pts, aes(date, y), shape = 1, colour = col_obs,
                             alpha = 0.25, size = 1.1)} +
      geom_line(data = lines, aes(date, y, colour = climate),
                linewidth = if (k == 1) 0.4 else 1, na.rm = TRUE) +
      geom_text(data = key, aes(date, y, label = label, colour = climate, vjust = vjust),
                hjust = 0, fontface = "bold", size = 4) +
      scale_colour_manual(values = c("Current climate" = col_obs, "Warmer climate" = col_proj),
                          guide = "none") +
      facet_wrap(~panel, ncol = 1, scales = "free_y") +
      scale_x_date(date_breaks = "6 months", date_labels = "%b\n%Y") +
      scale_y_continuous(labels = function(x) {
        if (input$ts_unit == "usd" && max(x, na.rm = TRUE) < 40) paste0("$", x) else x
      }) +
      labs(x = NULL, y = NULL) +
      theme_site() +
      theme(panel.grid.minor = element_blank(),
            strip.text = element_text(hjust = 0, size = 12, face = "bold", colour = col_ink),
            panel.spacing.y = unit(12, "pt"))
  }, res = 96)

  output$ts_note <- renderText({
    eq <- if (alt_on()) sprintf(" Both lines assume: %s (illustrative).", alt_label()) else ""
    smooth <- switch(input$smooth, "1" = "Daily values.",
                     "7" = "Centered 7-day averages.", "30" = "Centered 30-day averages.")
    warm <- if (isTRUE(input$ts_warmer)) {
      paste0(" Warmer climate: observed use plus the predicted change ",
             "f(projected temperature) \u2212 f(observed temperature) for each day, and the ",
             "projected temperature below.")
    } else " Check \u201cShow the warmer climate\u201d to add the projection."
    paste0("Observed daily electricity use (top) and average daily temperature (bottom). ",
           smooth, if (input$smooth != "1") " Points: observed days." else "", warm, eq)
  })

  output$p_hist <- renderPlot({
    tn <- as.vector(t_new())
    h <- rbind(
      data.frame(t = d$tavg, which = "Observed", w = 1 / nrow(d)),
      data.frame(t = tn, which = "Projected", w = 1 / length(tn))
    )
    h$which <- factor(h$which, levels = c("Observed", "Projected"))
    ggplot(h, aes(t, weight = w)) +
      annotate("rect", xmin = t_max_obs, xmax = 105, ymin = -Inf, ymax = Inf,
               fill = "#eceef0") +
      geom_histogram(data = h[h$which == "Observed", ], binwidth = 2.5,
                     boundary = 0, fill = col_obs, colour = "#fcfcfb", alpha = 0.7) +
      geom_step(data = transform(h[h$which == "Projected", ]),
                stat = "bin", binwidth = 2.5, boundary = 0, direction = "mid",
                colour = col_proj, linewidth = 1) +
      annotate("text", x = 22, y = Inf, vjust = 1.5, hjust = 0, label = "Observed",
               colour = col_obs, fontface = "bold") +
      annotate("text", x = 22, y = Inf, vjust = 3.2, hjust = 0, label = "Projected",
               colour = col_proj, fontface = "bold") +
      scale_x_continuous(breaks = seq(20, 100, 10), limits = c(15, 105)) +
      scale_y_continuous(labels = function(x) paste0(round(100 * x), "%")) +
      labs(x = "Average daily temperature (°F)", y = "Share of days") +
      theme_site() +
      theme(panel.grid.minor = element_blank())
  }, res = 96)

  output$p_models <- renderPlot({
    req(input$climate == "cmip6", has_cmip)
    bm <- res()$by_model
    req(ncol(bm) > 1)
    m <- data.frame(model = colnames(bm), pct = bm["pct", ])
    m$model <- factor(m$model, levels = m$model[order(m$pct)])
    ggplot(m, aes(pct, model)) +
      geom_vline(xintercept = mean(m$pct), colour = col_proj, linetype = "dashed") +
      geom_segment(aes(x = 0, xend = pct, yend = model), colour = "#c9ced4") +
      geom_point(colour = col_proj, size = 3) +
      annotate("text", x = mean(m$pct), y = Inf, vjust = -0.4, hjust = -0.05,
               label = "average", colour = col_proj, size = 3.5) +
      coord_cartesian(clip = "off") +
      labs(x = "Change in daily electricity use (%)", y = NULL) +
      theme_site() +
      theme(panel.grid.minor = element_blank(), panel.grid.major.y = element_blank(),
            plot.margin = margin(18, 8, 4, 4))
  }, res = 96)
}

shinyApp(ui, server)
